struct Control {
    std::array<std::uint16_t,56> table;
    std::uint16_t indexA,indexB;
    std::int16_t active,spawned;
    std::uint8_t slot;
    std::uint64_t beforeHash,afterHash;
    std::uint16_t allocationCount;
    std::array<std::uint16_t,2> enemyCounts;
    std::vector<std::uint8_t> actor;
    std::array<std::uint16_t,112> future;
};
std::uint64_t hash(const std::vector<NormalWorkOperation>& operations) {
    std::uint64_t result=14695981039346656037ULL,pending=0;
    const auto add=[&](auto kind,auto count){result=(result^std::uint64_t(kind))*1099511628211ULL;result=(result^count)*1099511628211ULL;};
    for(const auto& op:operations){
        if(op.kind==NormalWorkKind::instructions){pending+=op.count;continue;}
        if(pending!=0){add(NormalWorkKind::instructions,pending);pending=0;}add(op.kind,op.count);
    }
    if(pending!=0){add(NormalWorkKind::instructions,pending);}return result;
}
std::vector<Model3d> models() {
    std::vector<Model3d> out(44);
    for(const auto type:{1,3,11}){auto& model=out[type];model.scaleShift=0;model.flags=1;
        model.collisionRadius=type==1?1342:type==3?770:748;}
    out[11].animationLimits={8};return out;
}
Level1PeriodicSpawnInput input(const Control& c) {
    Level1PeriodicSpawnInput out{c.active,c.spawned,10,6,16,{}};
    for(std::size_t i=0;i<out.ordinaryPool.size();++i){out.ordinaryPool[i].health=i<c.slot?1:0;out.ordinaryPool[i].entityIndex=i;}
    return out;
}
std::vector<std::uint8_t> record(const Level1Entity& actor) {
    std::vector<std::uint8_t> out(99);
    const auto word=[&](std::size_t off,std::uint16_t value){out[off]=static_cast<std::uint8_t>(value);out[off+1]=static_cast<std::uint8_t>(value>>8U);};
    const auto dword=[&](std::size_t off,std::uint32_t value){word(off,static_cast<std::uint16_t>(value));word(off+2,static_cast<std::uint16_t>(value>>16U));};
    word(2,static_cast<std::uint16_t>(actor.type));dword(4,actor.collisionRadius);
    dword(8,static_cast<std::uint32_t>(actor.position.x));dword(12,static_cast<std::uint32_t>(actor.position.y));dword(16,static_cast<std::uint32_t>(actor.position.z));
    word(0x18,actor.yaw);word(0x3c,static_cast<std::uint16_t>(actor.forwardVelocity));
    if(actor.type==11){word(0x1a,0x130c);word(0x1c,0x9000);}
    std::copy(actor.stateBytes4dTo52.begin(),actor.stateBytes4dTo52.end(),out.begin()+0x4d);out[0x59]=actor.weaponSlotCount;
    return out;
}
